import json, re, html
from pathlib import Path

ROOT = Path('/opt/data/n8n-docs-site')
PKG = ROOT / 'vendor/package'
OUT = ROOT / 'site'
OUT.mkdir(exist_ok=True)
pkg = json.loads((PKG / 'package.json').read_text())
version = pkg['version']

def esc(v):
    return html.escape(str(v), quote=True)

def node_inventory():
    out=[]; seen=set()
    for entry in pkg['n8n']['nodes']:
        src=entry.replace('dist/','').replace('.node.js','').replace('.js','')
        slug=src.split('/')[-1]
        ident='n8n-nodes-base.'+slug
        if ident in seen: continue
        seen.add(ident)
        name=re.sub(r'(?<!^)(?=[A-Z])',' ',slug).strip()
        name=name.title() if name.islower() else name
        low=src.lower()
        if any(x in low for x in ['trigger','webhook','schedule','cron','poll']): cat='Triggers & Webhooks'
        elif any(x in low for x in ['google','microsoft','slack','discord','telegram','email','smtp','notion','airtable','hubspot','salesforce','jira','linear','github','gitlab','twilio']): cat='Apps & SaaS'
        elif any(x in low for x in ['postgres','mysql','mongo','redis','elastic','supabase','sqlite','mariadb','snowflake','mssql','oracle','couchbase']): cat='Databases & Storage'
        elif any(x in low for x in ['openai','anthropic','gemini','ollama','hugging','pinecone','vector','embedding','langchain','ai']): cat='AI & LangChain'
        elif any(x in low for x in ['http','graphql','ftp','ssh','websocket','rss','xml','html']): cat='HTTP & Data Access'
        elif any(x in low for x in ['file','spreadsheet','csv','json','pdf','compression','binary']): cat='Files & Formats'
        elif any(x in low for x in ['if','switch','merge','split','loop','wait','execute','code','set','edit','filter','sort','limit','aggregate','item']): cat='Flow & Data Transformation'
        else: cat='Utilities & Other'
        out.append({'id':ident,'name':name,'cat':cat,'src':src})
    return sorted(out,key=lambda x:(x['cat'],x['name'].lower()))

nodes=node_inventory()
cats=[]
for n in nodes:
    if n['cat'] not in cats: cats.append(n['cat'])

