palette={'Triggers & Webhooks':'#ffb55b','Apps & SaaS':'#6ecbff','Databases & Storage':'#8be28b','AI & LangChain':'#d59bff','HTTP & Data Access':'#65dfcf','Files & Formats':'#ffd36e','Flow & Data Transformation':'#ff8eaf','Utilities & Other':'#b5c7d9'}

def mini_flow(flow):
    parts=[p.strip() for p in flow.split('→')]
    nodes_html=[]
    for i,p in enumerate(parts):
        color=palette['Triggers & Webhooks'] if i==0 else palette['Flow & Data Transformation'] if i<len(parts)-1 else palette['Apps & SaaS']
        nodes_html.append(f'<span class="editor-node" style="--node-accent:{color}"><span class="node-icon">{esc(p[:1])}</span><span>{esc(p)}</span></span>')
    return '<div class="flow">'+'<span class="flow-arrow">→</span>'.join(nodes_html)+'</div>'

examples_cards=''.join(f'<article class="example-card" data-search="{esc((title+" "+domain+" "+flow+" "+desc).lower())}"><div class="example-head"><span class="example-number">{num}</span><div><span class="kicker">{esc(domain)}</span><h3>{esc(title)}</h3></div></div>{mini_flow(flow)}<p>{esc(desc)}</p><details><summary>Implementation checklist</summary><ul><li>Define the input and output schema before configuring nodes.</li><li>Use credentials, bounded retries, and an explicit error path.</li><li>Make external writes idempotent and record a correlation ID.</li><li>Test the happy path, duplicate delivery, timeout, and partial failure.</li></ul></details></article>' for num,title,domain,flow,desc in examples)

